#!/usr/bin/env sh
# Generated by ~/.config/hypr/shell.lua
# Style: gruvbox-dark-blue-aqua

# Only apply in interactive terminals.
case "$-" in
  *i*) ;;
  *) return 0 2>/dev/null || exit 0 ;;
esac

# OSC helper. ST terminator is ESC backslash.
osc() { printf '\033]%s\033\\' "$1"; }

# Terminal foreground, background, cursor.
osc '10;#ebdbb2'
osc '11;#282828'
osc '12;#83a598'

# ANSI palette.
osc '4;0;#1d2021'
osc '4;1;#fb4934'
osc '4;2;#8ec07c'
osc '4;3;#fabd2f'
osc '4;4;#83a598'
osc '4;5;#83a598'
osc '4;6;#8ec07c'
osc '4;7;#ebdbb2'
osc '4;8;#928374'
osc '4;9;#fb4934'
osc '4;10;#8ec07c'
osc '4;11;#fabd2f'
osc '4;12;#83a598'
osc '4;13;#83a598'
osc '4;14;#8ec07c'
osc '4;15;#fbf1c7'

# Optional readline/fzf-ish defaults for tools that honor env colors.
export FZF_DEFAULT_OPTS=${FZF_DEFAULT_OPTS:-'--color=fg:#ebdbb2,bg:#282828,hl:#83a598,fg+:#fbf1c7,bg+:#32302f,hl+:#8ec07c,info:#a89984,prompt:#83a598,pointer:#8ec07c,marker:#8ec07c'}
